    /**
     * Setup a Denver to Colorado dev plan.
     */
    protected setupKdenKcos(): Promise<void>;
    /**
     * Setup a Christchurch RW20 to Invercargill RW22 dev plan.
     * ATSAT1Q IDARA CHNV3 DUKOP DUKOP6B
     */
    protected setupNzchNznv(): Promise<void>;
