/** A set of functions for modifying a flight plan in the simplest way possible. */
declare class DevPlanUtils {
    private readonly fms;
    /**
     * ctor
     * @param fms The FMS instance to use.
     */
    constructor(fms: Fms);
    /**
     * Sets the origin for the flight plan.
     * @param ident The ICAO to set, like 'KDEN'.
     * @returns The origin facility.
     */
    setOrigin(ident: string): Promise<AirportFacility>;
    /**
     * Sets the origin for the flight plan.
     * @param origin The origin facility. Get this by calling setOrigin first.
     * @param runwayName The runway to set, like '34L'.
     * @returns The runway.
     * @throws Error if runway couldn't be found with given inputs.
     */
    setOriginRunway(origin: AirportFacility, runwayName: string): OneWayRunway;
    /**
     * Sets the destination for the flight plan.
     * @param ident The ICAO to set, like 'KCOS'.
     * @returns The destination facility.
     */
    setDestination(ident: string): Promise<AirportFacility>;
    /** Removes the origin. */
    removeOrigin(): void;
    /** Removes the destination. */
    removeDestination(): void;
    /**
     * Sets the destination for the flight plan.
     * @param ident The ident to search for.
     * @param segmentIndex The index of the segment to add the waypoint to.
     * @param segmentLegIndex The index inside the segment to insert the waypoint at (if none, append).
     * @returns The destination facility.
     */
    insertWaypoint(ident: string, segmentIndex: number, segmentLegIndex?: number): Promise<Facility>;
    /**
     * Sets the destination for the flight plan.
     * @param airwayName The name of the airway.
     * @param entryIdent The ident for the airway entry.
     * @param exitIdent The ident for the airway exit.
     * @param segmentIndex The index of the segment to add the waypoint to.
     * @param segmentLegIndex The index inside the segment to insert the waypoint at (if none, append).
     * @returns The destination facility.
     */
    insertAirway(airwayName: string, entryIdent: string, exitIdent: string, segmentIndex: number, segmentLegIndex: number): Promise<[AirwayData, IntersectionFacility, IntersectionFacility]>;
    /**
     * Checks for an airway at a leg and returns the airway.
     * @param entryIdent The icao of the entry to check.
     * @param airwayName The airway to search for.
     * @returns The airway object.
     */
    getAirwayFromLeg(entryIdent: string, airwayName: string): Promise<AirwayData>;
    /**
     * Searches for facilities matching ident, returns the nearest one.
     * @param ident The intersection ident to search for.
     * @returns The selected facility.
     */
    findNearestIntersectionFromIdent(ident: string): Promise<IntersectionFacility>;
    /**
     * Searches for facilities matching ident, returns the nearest one.
     * @param ident The ident to search for.
     * @param facilityType The facility type to search for.
     * @returns The selected facility.
     */
    findNearestFacilityFromIdent(ident: string, facilityType?: any): Promise<Facility>;
    /**
     * Loads a departure.
     * @param origin The origin facility. Get this by calling setOrigin first.
     * @param departureName The departure name, like 'BAYLR6'.
     * @param runwayName The name of the runway, like '34L'.
     * @param transitionName The name of the enroute transition, like 'HBU'.
     * @throws Error if something couldn't be found with given inputs.
     * @returns true on success
     */
    loadDeparture(origin: AirportFacility, departureName: string, runwayName: string, transitionName?: string): Promise<boolean>;
    /**
     * Loads an arrival.
     * @param destination The destination facility. Get this by calling setDestination first.
     * @param arrivalName The name of the arrival, like 'DBRY4'.
     * @param transitionName The name of the arrival transition, like 'ALS'.
     * @param runwayTransitionName The name of the arrival runway transition, like '17R'.
     * @throws Error if something couldn't be found with given inputs.
     * @returns true on success
     */
    loadArrival(destination: AirportFacility, arrivalName: string, transitionName?: string, runwayTransitionName?: string): Promise<boolean>;
    /**
     * Loads an approach.
     * @param destination The destination facility. Get this by calling setDestination first.
     * @param approachName The name of the approach, like 'ILS 17L'.
     * @param transitionName The name of the approach transition, like 'BRK' or 'ADANE'.
     * @throws Error if something couldn't be found with given inputs.
     */
    loadApproach(destination: AirportFacility, approachName: string, transitionName?: string): Promise<void>;
}

/**
 * Flight plan user data keys.
 */
declare enum FmsFplUserDataKey {
    /** The name of the flight plan. */
    Name = "name",
    /** Data describing the flight plan's loaded visual approach procedure. */
    VisualApproach = "visual_approach_data",
    /** Data describing the flight plan's loaded VFR approach procedure. */
    VfrApproach = "vfr_approach_data",
    /** Whether the flight plan's loaded approach procedure skips an initial course reversal. */
    ApproachSkipCourseReversal = "skipCourseReversal",
    /**
     * Whether the current DTO to an existing leg is created by the user from the direct to dialog.
     * Excludes other types of direct to e.g. activating a leg.
     */
    DtoExistingIsUser = "dto_existing_user",
    /** Whether the flight plan is activated. */
    IsActivated = "is_activated"
}
/**
 * Data describing a visual approach procedure that is loaded into a flight plan.
 */
type FmsFplVisualApproachData = {
    /** The designation of the runway associated with the loaded visual approach procedure. */
    runwayDesignation: string;
};
/**
 * Data describing a VFR approach procedure that is loaded into a flight plan.
 */
type FmsFplVfrApproachData = {
    /** The index of the published approach procedure on which the loaded VFR approach is based. */
    approachIndex: number;
    /** Whether the loaded approach is a vectors-to-final (VTF) approach. */
    isVtf: boolean;
};
/**
 * Mappings from flight plan user data keys to their data types.
 */
type FmsFplUserDataTypeMap = {
    /** The name of the flight plan. */
    [FmsFplUserDataKey.Name]: string;
    /** Data describing the flight plan's loaded visual approach procedure. */
    [FmsFplUserDataKey.VisualApproach]: Readonly<FmsFplVisualApproachData>;
    /** Data describing the flight plan's loaded VFR approach procedure. */
    [FmsFplUserDataKey.VfrApproach]: Readonly<FmsFplVfrApproachData>;
    /** Whether the flight plan's loaded approach procedure skips an initial course reversal. */
    [FmsFplUserDataKey.ApproachSkipCourseReversal]: boolean;
    /**
     * Whether the current DTO to an existing leg is created by the user from the direct to dialog.
     * Excludes other types of direct to e.g. activating a leg.
     */
    [FmsFplUserDataKey.DtoExistingIsUser]: boolean;
    /** Whether the flight plan is activated. */
    [FmsFplUserDataKey.IsActivated]: boolean;
};
/**
 * IFD flight plan leg user data items.
 */
declare enum FmsFplLegUserDataKey {
    /** The type of approach the leg is associated with, only used on the FAF leg for each approach in the plan. */
    ApproachType = "approachType",
    /** The RNAV type of the approach the leg is associated with, only used on the FAF leg for each approach in the plan. */
    ApproachTypeFlags = "approachTypeFlags",
    /** The discontinuity type for UI display. Used on all discontinuity legs. */
    DiscontinuityType = "discontinuityType"
}
/**
 * IFD flight plan leg user data item types.
 */
type FmsFplLegUserDataTypeMap = {
    /** The type of approach the leg is associated with. */
    [FmsFplLegUserDataKey.ApproachType]: ExtendedApproachType;
    /** The RNAV type of the approach the leg is associated with. */
    [FmsFplLegUserDataKey.ApproachTypeFlags]: RnavTypeFlags;
    /** The discontinuity type for UI display. Used on all discontinuity legs. */
    [FmsFplLegUserDataKey.DiscontinuityType]: IfdDiscontinuityType;
};

